ROOT=Path(__file__).resolve().parents[3];HERE=Path(__file__).resolve().parent
DAY='2026-10-25';REV='1.181';BASE='1.180';PRE='ha181_';PID='benedict_anderson'
G=json.loads((ROOT/'historiography-1920-2000.json').read_text());N={x['id']:x for x in G['nodes']};P={x['id']:x for x in G['people']};S={x['id']:x for x in G['sources']}
assert G['revision_history'][-1]['version']==BASE and PID not in N and PID in P
sources=[]
def src(k,title,url,note,primary=False):
 s=dict(id=PRE+k,title=title,citation=title,url=url,verification=dict(status='supporting_page_checked' if primary else 'bibliographic_metadata_checked',checked_on=DAY,note=note));sources.append(s);return s['id']
def ev(k,label,year,sids,support,kind='publication'):
 return dict(id=PRE+k,label=label,kind=kind,track='editions' if kind in ['edition','translation'] else ('reception' if kind=='reception' else 'contributions'),date=dict(year=year,precision='year'),source_ids=['graph:'+s for s in sids],support=support)
def write(path,obj):
 p=HERE/path;p.parent.mkdir(parents=True,exist_ok=True);p.write_text(json.dumps(obj,ensure_ascii=False,indent=2)+'\n')
ic=src('ic1991','Benedict Anderson, Imagined Communities, revised and extended edition (Verso, 1991): selected primary pages.','https://tengkudhaniiqbal.wordpress.com/wp-content/uploads/2014/11/imagined-communities-benedict-anderson.pdf','Public scan, not a publisher-hosted file. Copyright leaf visually/OCR checked: first published 1983, revised and extended edition 1991. Introduction printed pp. 2–7 read in page OCR, with pp. 4–5 visually checked; printed pp. 163–167 (opening of Census, Map, Museum) read in OCR; preface xi–xv read in university transcription and xiv–xv visually compared. OCR is imperfect: paraphrase only, no exact quotations. These selected pages are not a reading of the whole 1991 book, a collation against the 1983 text or a reading of the complete census/map/museum chapter.',True)
pr=src('preface1991','Benedict Anderson, Preface to the second edition of Imagined Communities, signed February 1991; Michigan Tech reserve transcription.','https://pages.mtu.edu/~rlstrick/rsvtxt/anderprf.htm','Entire preface transcription read, printed xi–xv; final two pages compared to scan. Host header says 1989, conflicting with the signed February 1991 preface and primary copyright leaf; that header is not used as an edition date. The author identifies corrections, retitling of Creole Pioneers, and the added Census, Map, Museum and Memory and Forgetting chapters; he describes the latter as tentative and limits the former empirical materials to Southeast Asia. Main text largely retained is his report, not a fresh textual collation.',True)
fo=src('foo2009','Cynthia Foo, interview with Benedict Anderson, Invisible Culture 13, Spring 2009.','https://www.rochester.edu/in_visible_culture/Issue_13_/foo/index.html','Primary answers read from the opening Kwee Thiam Tjing project question through the discussion of multilingual local cosmopolitanism, ending before the question beginning the broader colonization/transnationalism discussion. Introductory account of the 1 October 2008 Columbia talk is distinguished from Anderson’s answers. Original issue index https://www.rochester.edu/in_visible_culture/Issue_13_/index.html verifies Spring 2009; a later journal-platform posting is not the original publication. Exact conversation date unestablished. Remaining interview, underlying historical documents and planned biography unread; no published completed Kwee book asserted.',True)
uf=src('rooster','Benedict Anderson, Under Three Flags prologue and A Life Beyond Boundaries methodological reflection, selected Verso excerpt.','https://www.versobooks.com/en-gb/blogs/news/2705-the-rooster-s-egg-isabelo-de-los-reyes-and-el-folk-lore-filipino','Read the complete quoted memoir paragraph on moving beyond self-contained national comparisons, plus the prologue opening through the initial Isabelo de los Reyes / New Science discussion (approximately first 9,500 characters of the extracted page). Rest of this long posting and both complete books unread. The memoir quotation is later retrospective testimony; the following prologue originally belongs to Under Three Flags (2005), subsequently retitled The Age of Globalization. The web repost does not date the original prologue to 2016. No equal dissertation uptake across these books inferred.',True)
os=src('oldstate1983','Benedict Anderson, “Old State, New Society: Indonesia’s New Order in Comparative Historical Perspective,” Journal of Asian Studies 42:3 (May 1983), 477–496.','https://www.cambridge.org/core/journals/journal-of-asian-studies/article/abs/old-state-new-society-indonesias-new-order-in-comparative-historical-perspective/779517B1E99B753FB926C5F99FA0393A','Complete publicly displayed author extract and bibliographic header read, not the full article. Extract distinguishes nation from state and proposes institutional state interests and colonial-state continuities as explanations of New Order policies. DOI 10.2307/2055514, May 1983 print date; Cambridge online posting 23 March 2011 is separate. This is a bounded primary formulation, not independent proof of the historical thesis.',True)
cr=src('cribb2010','Robert Cribb, “The Historical Roots of Indonesia’s New Order: Beyond the Colonial Comparison,” in Edward Aspinall and Greg Fealy, eds., Soeharto’s New Order and its Legacy (ANU E Press, 2010), ch. 5.','https://press-files.anu.edu.au/downloads/press/p687/html/ch05.xhtml?page=11&referer=','Read opening historical/model discussion through its reconstruction of Anderson’s state thesis (approximately first 11,000 extracted characters), and ending development comparison plus complete “Conclusion: dualism and historical roots” (approximately last 6,500). Middle chapter unread. Named reader’s challenge to a simple resurrection/dualism model is attributed to Cribb; he emphasizes multiple historical inheritances, including Japanese occupation and postindependence regimes. This critiques the Indonesian-state thesis, not every claim in Imagined Communities. Official book landing verifies 2010: https://press.anu.edu.au/publications/series/asian-studies/soehartos-new-order-and-its-legacy .',True)
ka=src('kammen2017','Douglas Kammen, “The Cornell Paper: How It Was Done,” Indonesia 104 (October 2017), 1–26.','https://ecommons.cornell.edu/entities/publication/201549e2-bb46-4dd4-8276-609201f5316c','Institutional abstract and indexed primary opening p. 1 with notes 1–2 checked; full article and original Cornell Paper unread. Supports completion/circulation in January 1966 and formal publication in 1971. Notes credit Anderson and Ruth T. McVey, with research assistance from Frederick P. Bunnell; Bunnell assisted research rather than writing the final text. Original 1971 title is A Preliminary Analysis of the October 1, 1965, Coup in Indonesia, Cornell Modern Indonesia Project Interim Reports 52. Equinox 2009 is a reprint, not original publication. No endorsement of the paper’s provisional coup explanation.')
ja=src('java1972','CiNii institutional catalogue, Java in a Time of Revolution: Occupation and Resistance, 1944–1946 (Cornell University Press, 1972).','https://ci.nii.ac.jp/ncid/BA02951903.amp','Title, Anderson authorship, Cornell imprint and 1972 original checked in institutional catalogue; WorldCat record https://search.worldcat.org/title/202174 corroborates. Subtitle is 1944–1946; a malformed Google Books subtitle ending 1966 is excluded. Book body unread.')
lp=src('language1990','Language and Power: Exploring Political Cultures in Indonesia (Cornell University Press, 1990), contemporary review header.','https://www.cambridge.org/core/journals/journal-of-asian-studies/article/abs/language-and-power-exploring-political-cultures-in-indonesia-by-benedict-r-og-anderson-ithaca-cornell-university-press-1990-305-pp-4495-cloth-1495-paper/E28417FED10A26F36D339489ABCF6EF9','William H. Frederick’s 1991 JAS review header verifies Cornell University Press 1990 original; review body unread. CiNii https://ci.nii.ac.jp/ncid/BC1727533X identifies the Equinox 2006 reprint and original 1990 imprint. A collection of essays; the separately checked Old State essay remains 1983. Cornell obituary’s 1991 year is not adopted; Cambridge web-posting 2011 is not original publication. No whole-collection reading.')
sp=src('spectre1998','Verso / Penguin Random House, The Spectre of Comparisons: Nationalism, Southeast Asia and the World.','https://www.penguinrandomhouse.com/books/233141/the-spectre-of-comparisons-by-benedict-anderson/','Publisher/distributor author, title, 17 September 1998 publication and essay-collection metadata checked. No chapter body read; publisher description alone does not establish an argument or relation.')
edi=src('ic2006','Verso / Penguin Random House, Imagined Communities: edition and format metadata.','https://www.penguinrandomhouse.com/books/232489/imagined-communities-by-benedict-anderson/9781784786755/','Publisher/distributor distinguishes 17 November 2006 ebook from 13 September 2016 paperback. 2006 revised edition contents with new Travel and Traffic afterword cross-checked in https://openlibrary.org/books/OL20914401M/Imagined_communities . Selected original/revised text dates remain 1983/1991. Afterword body unread; no argument attributed from its title. Day-specific format date not generalized to every 2006 manifestation.')
jm=src('memoir2009','CiNii institutional records, Japanese and English editions of Anderson’s memoir.','https://ci.nii.ac.jp/ncid/BD01713209?l=en','Revised 2023 Japanese record identifies Anderson as author and 加藤剛 (Tsuyoshi Kato) as translator, with NTT original ヤシガラ椀の外へ (2009). Record https://ge.nii.ac.jp/ncid/BB26961840 explicitly distinguishes Japanese NTT 2009 original, English Verso 2016 first publication, and Malaysian SIRD 2016 issue. These are separate manifestations; 2023 retitled revised Japanese edition not dated to 2009. No complete memoir or translator’s essay read; do not describe English revision as a mechanically identical translation.')
rh=src('rural2012','CiNii institutional catalogue, The Fate of Rural Hell: Asceticism and Desire in Buddhist Thailand (Seagull, 2012).','https://ge.nii.ac.jp/ncid/BB09788557','Institutional record verifies Seagull 2012 original, viii + 99 pages, ISBN 9780857420275. Chicago distributor current page https://press.uchicago.edu/ucp/books/book/distributed/F/bo281230758.html describes the second edition, copyright 2016, not original 2012. Book body unread; title/description create no new substantive relation.')
ag=src('age2013','Verso / Penguin Random House, The Age of Globalization: Anarchists and the Anticolonial Imagination.','https://www.penguinrandomhouse.com/books/228905/the-age-of-globalization-by-benedict-anderson/9781781681442/','Publisher/distributor verifies 5 November 2013 paperback and ebook and explicitly identifies previous publication as Under Three Flags. Retitling/reissue, not a separate second original research book; original 2005 date independently stated in publisher’s primary prologue posting. Full book unread.')
me=src('memoir2016','Verso, A Life Beyond Boundaries: A Memoir; first English edition 2016.','https://www.versobooks.com/products/219-a-life-beyond-boundaries','Publisher title/author and edition metadata checked; current default is a later 2018 paperback, not the first English publication. Institutional edition record https://ge.nii.ac.jp/ncid/BB26961840 explicitly gives first English Verso 2016. Primary body read only in the separately identified retrospective paragraph on the rooster excerpt page. Full memoir unread. English publication is posthumous after the independently sourced 13 December 2015 death.')
li=src('cornell_life','Blaine Friedlander, “Benedict Anderson, who wrote Imagined Communities, dies,” Cornell Chronicle, 15 December 2015.','https://news.cornell.edu/stories/2015/12/benedict-anderson-who-wrote-imagined-communities-dies','Complete short institutional obituary read. Supports birth 26 August 1936, Kunming, and death 13 December 2015, East Java, Indonesia; no exact local death place asserted beyond institutional witness. Identifies Cornell emeritus scholar and Imagined Communities author. Its Language and Power year (1991) conflicts with the contemporary review/catalogue original 1990, and is not used for that publication fact. Institutional praise and the quoted 2014 interview are not evidence of universal influence.',True)
