relations=[]
def rel(k,source,target,text,sids,note,kind='contribution'):
 r=dict(proposal_id=PRE+k,source=source,target=target,relationship=text,source_ids=sids,evidence_note=note,relationship_kind=kind,type='critique' if kind=='critique' else 'connection',directed=True,classification_basis='editorial_review');relations.append(r);return r
rel('national',PID,'nationalismstudies','Explains national fellowship through historically formed imagining and vernacular print markets; imagined membership does not mean falsity or personal acquaintance.',[ic,ori],'Selected Introduction pp. 2–7 and complete publisher print excerpt. Limited/sovereign community and horizontal fellowship are his analytical proposals despite actual inequality. Print capitalism opens possibilities; the excerpt explicitly rejects an automatic equation of language reach with state boundaries. No citation-derived influence claim.')
rel('state',PID,'political','Distinguishes the state’s institutional interests from the nation and investigates colonial continuities in Indonesia’s New Order.',[os,cr],'Anderson’s complete displayed 1983 author extract, full article unread. Cribb’s specifically named 2010 reading contests a simple colonial resurrection, stressing mixed historical inheritances. The relation identifies a historical research problem and disputed thesis, not an endorsed single genealogy.')
rel('space',PID,'spatialhistory','Examines how colonial census classifications, territorial maps and museums organize the space and historical ancestry available to national imagining.',[pr,ic],'1991 preface xi–xv and Census, Map, Museum opening pp. 163–167. Census/map/museum architecture is identified in the preface; census classification opening is read directly. Southeast Asian empirical scope and author’s tentative framing retained; entire map and museum sections unread. These additions are not silently dated to 1983.')
rel('connected',PID,'global','Reconsiders nationally self-contained comparisons through anticolonial and anarchist connections, circulation and communication technologies.',[uf],'Own later memoir paragraph explicitly reflects on an earlier nation-by-nation method, and selected Under Three Flags prologue opening follows Isabelo de los Reyes. Later self-correction and book’s original 2005 date stay distinct; no comprehensive reading of its networks or claim of equal uptake with Imagined Communities.')
rel('life',PID,'biography','Uses the fragmentary, multilingual traces of Kwee Thiam Tjing to investigate local cosmopolitanism without assuming that cosmopolitan subjects must travel widely.',[fo],'Anderson’s own first interview answers in Spring 2009, distinguished from Foo’s account of the 2008 talk. The project remains unfinished in this testimony. No completed biography, transparent recovery of the subject, or general endorsement of every later historical assertion in the interview.')
rel('chatterjee','post',PID,'Partha Chatterjee’s 1993 intervention challenges Anderson’s modular derivation of colonized nationalisms and foregrounds autonomous cultural imagining in colonial Bengal.',['chatterjee_fragments'],'Specifically named critic, primary The Nation and Its Fragments pp. 4–7 freshly reread in rotated scan/OCR. Chatterjee acknowledges the print-capitalism insight while contesting derivative national models; material/spiritual distinction remains his historically situated claim. Postcolonial endpoint locates this named intervention because Chatterjee has a roster profile but no individual graph node; it asserts no field consensus. Existing collective arrows remain exact.',kind='critique')
works='A Preliminary Analysis of the October 1, 1965, Coup in Indonesia (with Ruth T. McVey; research assistance Frederick P. Bunnell; circulated 1966, published 1971); Java in a Time of Revolution (1972); Imagined Communities (1983; revised and extended 1991; 2006 edition with afterword); “Old State, New Society” (1983); Language and Power (1990, collected essays); The Spectre of Comparisons (1998, collected essays); Under Three Flags (2005; retitled The Age of Globalization, 2013); ヤシガラ椀の外へ (2009 Japanese memoir, translated by Tsuyoshi Kato); The Fate of Rural Hell (2012); A Life Beyond Boundaries (2016 first English memoir, posthumous).'
desc='A historian of Indonesia and comparative nationalism whose Imagined Communities treats national belonging as a historical cultural formation. Fellow members need not meet for a limited, sovereign community to become imaginable; its felt fellowship can coexist with exploitation and inequality. His account connects vernacular print markets, linguistic diversity and political imagination without making print language a ready-made map of state boundaries. The 1991 revision corrects earlier errors and adds colonial census, map and museum practices alongside memory and forgetting; these additions belong to the revised edition rather than automatically to 1983. Partha Chatterjee’s 1993 critique accepts the print insight while challenging a modular account that leaves colonized societies merely copying prior national forms. Its alternative foregrounds cultural sovereignty in colonial Bengal, not a timeless essence of every colonized society. Anderson’s Indonesian research also separates institutional state interests from national identification. Robert Cribb’s 2010 response contests a simple colonial resurrection of the New Order and stresses several historical inheritances. Later, Anderson himself identifies limits in treating nations as self-contained comparative units: the anticolonial connections of Under Three Flags and his unfinished multilingual Kwee Thiam Tjing biography project offer different research scales. These works contextualize his historical practice; their presence does not imply dissertation uptake equal to Imagined Communities.'
scope='Selected historical research connects Indonesia, comparative nationalism and anticolonial circulation. Argument claims rest on selected primary pages, the complete publisher print excerpt, selected interview answers and explicitly named critical readers. No complete monograph was newly read. Original, revised, translated, collected, retitled and posthumous publications retain dates and credits. Existing anderson and chatterjee_fragments source qualifications, nationalism roster/strand prose and all old collective relationships remain unchanged. Frozen dissertation-key counts are selection/reception evidence, not proof of individual readers’ agreement or influence; attribution contamination and overlapping variants prohibit treating the key as a clean person-authority total.'
node=dict(id=PID,label='Benedict Anderson',layer='historians',entry_kind='person',entry_type='Individual historian',period=None,hunt_core_paradigm=False,date_label='Imagined Communities (1983; revised 1991) · Indonesian research and later comparisons (selected facts 1966–2016)',description=desc,representative_figures_and_works=works,source_ids=['anderson','chatterjee_fragments']+[s['id'] for s in sources],scope_note=scope,chronology=dict(version=1,label='Selected research, publications, editions and named reception',selection_note='Seventeen selected dated facts, including distinct circulation/publication, original/revised/translation/retitling/posthumous manifestations and two explicitly named reception interventions; not a lifespan or comprehensive career interval.',events=events,intervals=[],continuation=dict(status='not_asserted',basis='Selected writing/publication/reception facts establish no continuous activity interval.'),interpretation='Metadata supports dates and credits only. Argument claims retain selected-primary or named-reader scopes; the 1991 revision is not silently projected into 1983.',prepared_on=DAY,editorial_record='data/production-batches/person-entries-1.181/acceptance.json'))
identity='Existing benedict_anderson identity reused: Benedict Richard O’Gorman Anderson (1936–2015), historian of Indonesia and author of Imagined Communities, matched by institutional obituary, primary publications and named-title metadata. Not Perry Anderson, historical trade-report authors or every item assigned to the frozen dissertation author key. No external-authority/name-variant union; source-specific earlier roster qualifications remain. Life evidence separately recorded in benedict_anderson/life-status.json.'
