pn=dict(person_id=PID,label='Benedict Anderson',identity_scope=identity,classification_decision='Historian layer follows explicit user classification; Cornell government-department appointment does not determine taxonomy. This editorial decision is private research metadata, not public scope prose.',existing_coverage=contexts,existing_sources_preserved=[copy.deepcopy(S[k]) for k in ['anderson','chatterjee_fragments','warwick_nationalism']],new_source_scopes=sources,reading_limit=scope,life_status_record=PID+'/life-status.json',events=events,relations=relations,unread=['No complete monograph newly read, including original 1983 IC, complete revised IC, Java, Language and Power, Spectre, Under Three Flags, Rural Hell and either complete memoir.','Cornell Paper body, full JAS article, complete Chatterjee volume, Cribb chapter middle, remaining Foo interview and Travel and Traffic afterword unread.'],selection=dict(person_key='P:anderson|benedict r',dated_first_author_count=716,main_work_key='W:anderson|imagined communities',main_work_dated_count=641,share_percent=89.5,scope='Coordinator’s separately reproduced frozen public dated first-author bibliography-key witnesses; not independently recomputed here. Raw all-year first-author 726 and main-work 647 include undated records. No all-authorship claim. Counts are not cleaned individual authority totals; malformed historical trade-report and likely Perry Anderson title contamination remain. Translation/title variants overlap and are not summed. Other-work and regional series remain in root’s independent panel, not historical-argument claims.'))
